create or replace function public.admin_live_coat_review_workspace()returns table(horse_id uuid,inventory_id uuid,name text,breed text,sex text,color text,image_url text,signature text,decision text,notes text,reviewed_at timestamptz)language plpgsql security definer set search_path=public as $$begin perform require_super_admin();return query select h.id,si.id,h.name::text,h.breed::text,h.sex::text,h.color::text,h.image_url::text,horse_visual_render_signature(h)::text,r.decision::text,r.notes::text,r.reviewed_at from store_inventory si join horses h on h.id=si.horse_id left join horse_visual_render_reviews r on r.signature=horse_visual_render_signature(h)where si.status='active'order by h.breed,h.sex,h.color,h.id;end$$;
revoke all on function public.admin_live_coat_review_workspace()from public,anon;
grant execute on function public.admin_live_coat_review_workspace()to authenticated;
